pragma solidity ^0.8.4;

import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import "@ensdomains/buffer/contracts/Buffer.sol";
import "../dnssec-oracle/DNSSEC.sol";
import "../dnssec-oracle/RRUtils.sol";
import "../registry/ENSRegistry.sol";
import "../root/Root.sol";
import "../resolvers/profiles/AddrResolver.sol";
import "../utils/BytesUtils.sol";
import "./DNSClaimChecker.sol";
import "./PublicSuffixList.sol";
import {IDNSRegistrar, DNS_REGISTRAR_V0_INTERFACE_ID} from "./IDNSRegistrar.sol";
import {NameCoder} from "../utils/NameCoder.sol";

/// @dev An ENS registrar that allows the owner of a DNS name to claim the
///      corresponding name in ENS.
///
/// Inception times are stored per name per type with a hash of the record data:
///     `uint256 hash := (uint256(keccak256(data)) << 32) + uint32(inception)`
///
contract DNSRegistrar is ERC165, IDNSRegistrar {
    using BytesUtils for bytes;
    using Buffer for Buffer.buffer;
    using RRUtils for *;

    /// @dev Precomputed labelhash of "_ens".
    bytes32 constant LABELHASH_PREFIX = keccak256("_ens");

    ENS public immutable ens;
    DNSSEC public immutable oracle;
    PublicSuffixList public suffixes;
    address public immutable previousRegistrar;
    address public immutable resolver;
    /// @dev Mapping from `(node, typeCovered)` to the last hashed inception.
    mapping(bytes32 node => mapping(uint16 typeCovered => uint256 hash))
        internal _inceptions;
    /// @dev Mapping to check if registrar was a DNSRegistrar deployment.
    mapping(address registrar => bool was) public wasRegistrar;

    /// @param previousRegistrars Addresses of previous DNSRegistrars. The first should the prior DNSRegistrar.
    /// @param _resolver Gasless DNSSEC resolver.
    /// @param _dnssec Shared DNSSEC implementation.
    /// @param _suffixes Shared PublicSuffixList implementation.
    /// @param _ens ENSv1 root registry.
    constructor(
        address[] memory previousRegistrars,
        address _resolver,
        DNSSEC _dnssec,
        PublicSuffixList _suffixes,
        ENS _ens
    ) {
        if (previousRegistrars.length > 0) {
            previousRegistrar = previousRegistrars[0]; // remember the latest
            for (uint256 i; i < previousRegistrars.length; ++i) {
                wasRegistrar[previousRegistrars[i]] = true;
            }
        }
        resolver = _resolver;
        oracle = _dnssec;
        suffixes = _suffixes;
        emit NewPublicSuffixList(address(suffixes));
        ens = _ens;
    }

    /// @dev This contract's owner-only functions can be invoked by the owner of the ENS root.
    modifier onlyOwner() {
        Root root = Root(ens.owner(bytes32(0)));
        address owner = root.owner();
        require(msg.sender == owner);
        _;
    }

    function setPublicSuffixList(PublicSuffixList _suffixes) public onlyOwner {
        suffixes = _suffixes;
        emit NewPublicSuffixList(address(suffixes));
    }

    /// @inheritdoc IDNSRegistrar
    function proveAndClaim(
        bytes memory name,
        DNSSEC.RRSetWithSignature[] memory input
    ) public override {
        (bytes32 rootNode, bytes32 labelHash, address addr) = _claim(
            name,
            input
        );
        ens.setSubnodeOwner(rootNode, labelHash, addr);
    }

    /// @inheritdoc IDNSRegistrar
    function proveAndClaimWithResolver(
        bytes memory name,
        DNSSEC.RRSetWithSignature[] memory input,
        address _resolver,
        address addr
    ) public override {
        (bytes32 rootNode, bytes32 labelHash, address owner) = _claim(
            name,
            input
        );
        if (msg.sender != owner) {
            revert PermissionDenied(msg.sender, owner);
        }
        ens.setSubnodeRecord(rootNode, labelHash, owner, _resolver, 0);
        if (addr != address(0)) {
            if (_resolver == address(0)) {
                revert PreconditionNotMet();
            }
            bytes32 node = NameCoder.namehash(rootNode, labelHash);
            // Set the resolver record
            AddrResolver(_resolver).setAddr(node, addr);
        }
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override returns (bool) {
        return
            interfaceId == type(IDNSRegistrar).interfaceId ||
            interfaceId == DNS_REGISTRAR_V0_INTERFACE_ID ||
            super.supportsInterface(interfaceId);
    }

    /// @inheritdoc IDNSRegistrar
    function getInception(
        bytes calldata name,
        uint16 typeCovered
    ) public view returns (uint32 inception, bytes28 recordHash) {
        (, uint256 hash) = _inceptionForType(name, typeCovered);
        inception = uint32(hash);
        recordHash = bytes28(bytes32(hash));
    }

    /// @inheritdoc IDNSRegistrar
    function inceptions(bytes32 node) external view returns (uint32) {
        return
            uint32(
                _leafInceptionWithFallback(
                    node,
                    NameCoder.namehash(node, LABELHASH_PREFIX)
                )
            );
    }

    function _claim(
        bytes memory name,
        DNSSEC.RRSetWithSignature[] memory input
    ) internal returns (bytes32 parentNode, bytes32 labelHash, address addr) {
        // early terminate if empty, otherwise DNSSEC reverts InvalidRRSet
        if (input.length == 0) {
            revert NoOwnerRecordFound();
        }

        RRUtils.SignedSet[] memory sss = oracle.verifyRRSetNow(input);

        // Get the first label
        uint256 offset;
        (labelHash, offset) = NameCoder.readLabel(name, 0);

        // Make sure the parent name is enabled
        parentNode = enableNode(name.substring(offset, name.length - offset));

        // ensure every inception in the chain not before the stored inception
        RRUtils.SignedSet memory ss;
        for (uint256 i; i < sss.length; ++i) {
            ss = sss[i];
            (bytes32 node, uint256 lastHash) = _inceptionForType(
                ss.name,
                ss.typeCovered
            );
            uint32 lastInception = uint32(lastHash); // time is lower 4 bytes, hash is upper 28 bytes
            uint256 hash = uint256(
                bytes32(bytes28(DNSClaimChecker.computeRecordHash(ss.data)))
            ) | ss.inception; // clear lower 4 bytes and replace with inception
            if (RRUtils.serialNumberGte(lastInception, ss.inception)) {
                // inception is same or older
                if (((lastHash ^ hash) >> 32) == 0) {
                    continue; // record unchanged, skip update
                }
                revert StaleProof(
                    ss.name,
                    ss.typeCovered,
                    lastInception,
                    bytes28(bytes32(lastHash)),
                    ss.inception,
                    bytes28(bytes32(hash))
                );
            }
            _inceptions[node][ss.typeCovered] = hash; // update
            emit InceptionUpdated(
                node,
                ss.typeCovered,
                ss.name,
                ss.inception,
                bytes28(bytes32(hash))
            );
        }

        // last proof must correspond to the "_ens.{name}" TXT record
        bool found;
        (addr, found) = DNSClaimChecker.getOwnerAddress(name, ss.data);
        if (!found) {
            revert NoOwnerRecordFound();
        }

        emit Claim(
            NameCoder.namehash(parentNode, labelHash),
            addr,
            name,
            ss.inception
        );
    }

    function enableNode(bytes memory domain) public returns (bytes32 node) {
        // Name must be in the public suffix list.
        if (!suffixes.isPublicSuffix(domain)) {
            revert InvalidPublicSuffix(domain);
        }
        return _enableNode(domain, 0);
    }

    function _enableNode(
        bytes memory domain,
        uint256 offset
    ) internal returns (bytes32 node) {
        (bytes32 labelHash, uint256 next) = NameCoder.readLabel(domain, offset);
        if (labelHash == bytes32(0)) {
            return bytes32(0);
        }
        bytes32 parentNode = _enableNode(domain, next);
        node = NameCoder.namehash(parentNode, labelHash);
        address owner = ens.owner(node);
        if (owner == address(0) || wasRegistrar[owner]) {
            if (parentNode == bytes32(0)) {
                Root root = Root(ens.owner(bytes32(0)));
                root.setSubnodeOwner(labelHash, address(this));
                ens.setResolver(node, resolver);
            } else {
                ens.setSubnodeRecord(
                    parentNode,
                    labelHash,
                    address(this),
                    resolver,
                    0
                );
            }
        } else if (owner != address(this)) {
            revert PreconditionNotMet();
        }
        return node;
    }

    /// @dev Determine the last inception hash for record type.
    function _inceptionForType(
        bytes memory name,
        uint16 typeCovered
    ) internal view returns (bytes32 node, uint256 inceptionHash) {
        (bytes32 labelHash, uint256 offset) = NameCoder.readLabel(name, 0);
        bytes32 parentNode;
        if (labelHash != bytes32(0)) {
            parentNode = NameCoder.namehash(name, offset);
            node = NameCoder.namehash(parentNode, labelHash);
        }
        inceptionHash = typeCovered == RRUtils.DNSTYPE_TXT &&
            labelHash == LABELHASH_PREFIX
            ? _leafInceptionWithFallback(parentNode, node)
            : _inceptions[node][typeCovered];
    }

    /// @dev Determine the last inception hash for `_ens.{name}` TXT.
    ///      Checks previous registrar if value is unset.
    /// @param parentNode Namehash of `name`.
    /// @param node Namehash of `_ens.{name}`.
    function _leafInceptionWithFallback(
        bytes32 parentNode,
        bytes32 node
    ) internal view returns (uint256 inceptionHash) {
        inceptionHash = _inceptions[node][RRUtils.DNSTYPE_TXT];
        if (inceptionHash == 0 && previousRegistrar != address(0)) {
            try DNSRegistrar(previousRegistrar).inceptions(parentNode) returns (
                uint32 t
            ) {
                inceptionHash = t; // only inception
            } catch {}
        }
    }
}
